#include <string>

const std::string PFAD = "/tmp/lernpfad_zeilen.txt";

int main() {
    {
        std::ofstream datei(PFAD);           // ueberschreibt die Datei
        if (!datei) {
            std::cerr << "Kann nicht schreiben!" << std::endl;
            return 1;
        }
        datei << "Zeile eins" << std::endl;
        datei << "Zeile zwei" << std::endl;
        datei << "Zeile drei" << std::endl;
    }                                        // hier schliesst die Datei

    std::ifstream lesen(PFAD);
    if (!lesen) {
        std::cerr << "Datei fehlt!" << std::endl;
        return 1;
    }

    int anzahl = 0;
    std::string zeile;
    while (std::getline(lesen, zeile)) {
        ++anzahl;
    }
    std::cout << anzahl << " Zeilen" << std::endl;

    lesen.close();
    std::remove(PFAD.c_str());
