const std::string PFAD = "/tmp/lernpfad_zahlen.txt";

int main() {
    {
        std::ofstream datei(PFAD);
        if (!datei) {
            std::cerr << "Kann nicht schreiben!" << std::endl;
            return 1;
        }
        datei << 4 << " " << 8 << " " << 15 << std::endl;
    }

    std::ifstream lesen(PFAD);
    if (!lesen) {
        std::cerr << "Datei fehlt!" << std::endl;
        return 1;
    }

    int zahl = 0;
    int anzahl = 0;
    int summe = 0;
    while (lesen >> zahl) {
        ++anzahl;
        summe += zahl;
    }
    std::cout << anzahl << " Zahlen, Summe " << summe << std::endl;

    lesen.close();
    std::remove(PFAD.c_str());
    return 0;
}

