#include <cstdio>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

const std::string PFAD = "/tmp/lernpfad_text.txt";

int main() {
    {
        std::ofstream datei(PFAD);
        if (!datei) {
            std::cerr << "Kann nicht schreiben!" << std::endl;
            return 1;
        }
        datei << "C++ liest Dateien" << std::endl;
        datei << "C++ schreibt Dateien" << std::endl;
        datei << "C++ schliesst Dateien" << std::endl;
    }

    std::ifstream lesen(PFAD);
    if (!lesen) {
        std::cerr << "Datei fehlt!" << std::endl;
        return 1;
    }

    int zeilen = 0;
    int woerter = 0;
    std::string zeile;
    while (std::getline(lesen, zeile)) {
        ++zeilen;
        std::istringstream strom(zeile);
        std::string wort;
        while (strom >> wort) {
            ++woerter;
        }
    }
    std::cout << zeilen << " Zeilen, " << woerter << " Woerter" << std::endl;

    lesen.close();
    std::remove(PFAD.c_str());
    return 0;
}
